$ErrorActionPreference = "Continue"

$RepoRoot = Split-Path -Parent $PSScriptRoot
$StartupFolder = [System.Environment]::GetFolderPath([System.Environment+SpecialFolder]::Startup)
$TargetVbs = Join-Path $StartupFolder "RunnerUp-AutoStart.vbs"
$SourceVbs = Join-Path $PSScriptRoot "start-runnerup-daemon.vbs"

# 1. Startup folder entry
$vbsContent = @"
' Auto-generated by Runner Up installer
Set objShell = CreateObject("WScript.Shell")
objShell.Run """wscript.exe"" """ & "$SourceVbs" & """", 0, False
"@

Set-Content -Path $TargetVbs -Value $vbsContent -Encoding ASCII
Write-Host "[1/3] Auto-start VBS entry installed at Startup folder:" -ForegroundColor Green
Write-Host "      $TargetVbs" -ForegroundColor Cyan

# 2. Registry CurrentVersion\Run entry (redundant safety)
try {
    $runCmd = "wscript.exe `"$SourceVbs`""
    Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run" -Name "RunnerUpSupervisor" -Value $runCmd -Force
    Write-Host "[2/3] Registry Run key configured successfully (HKCU\...\Run)." -ForegroundColor Green
} catch {
    Write-Host "[2/3] Notice: Registry Run key skipped: $_" -ForegroundColor Yellow
}

# 3. Scheduled Task with battery-sleep prevention
try {
    $taskName = "RunnerUpLiveSupervisor"
    $action = New-ScheduledTaskAction -Execute "wscript.exe" -Argument "`"$SourceVbs`""
    $trigger = New-ScheduledTaskTrigger -AtLogOn
    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Days 0)
    Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger -Settings $settings -Force | Out-Null
    Write-Host "[3/3] Windows Scheduled Task registered: '$taskName' (At Logon, runs on battery, no time limit)." -ForegroundColor Green
} catch {
    Write-Host "[3/3] Scheduled Task fallback: Startup folder will handle boot launch." -ForegroundColor Yellow
}

# 4. Enforce power settings immediately
try {
    powercfg /setacvalueindex SCHEME_CURRENT 4f971e89-eebd-4455-a8de-9e59040e7347 5ca83367-6e45-459f-a27b-476b1d01c936 0 2>&1 | Out-Null
    powercfg /setdcvalueindex SCHEME_CURRENT 4f971e89-eebd-4455-a8de-9e59040e7347 5ca83367-6e45-459f-a27b-476b1d01c936 0 2>&1 | Out-Null
    powercfg /setacvalueindex SCHEME_CURRENT SUB_SLEEP STANDBYIDLE 0 2>&1 | Out-Null
    powercfg /setdcvalueindex SCHEME_CURRENT SUB_SLEEP STANDBYIDLE 0 2>&1 | Out-Null
    powercfg /setacvalueindex SCHEME_CURRENT SUB_SLEEP HIBERNATEIDLE 0 2>&1 | Out-Null
    powercfg /setdcvalueindex SCHEME_CURRENT SUB_SLEEP HIBERNATEIDLE 0 2>&1 | Out-Null
    powercfg /setacvalueindex SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a 0 2>&1 | Out-Null
    powercfg /setdcvalueindex SCHEME_CURRENT 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a 0 2>&1 | Out-Null
    powercfg /setacvalueindex SCHEME_CURRENT SUB_NONE CONNECTIVITYINSTANDBY 1 2>&1 | Out-Null
    powercfg /setdcvalueindex SCHEME_CURRENT SUB_NONE CONNECTIVITYINSTANDBY 1 2>&1 | Out-Null
    powercfg /SetActive SCHEME_CURRENT 2>&1 | Out-Null
    Write-Host "[OK] Laptop Lid Close = Do Nothing, Sleep = Never, Wi-Fi = Max Performance." -ForegroundColor Green
} catch {}

Write-Host ""
Write-Host "PERMANENT AUTO-START INSTALLED SUCCESSFULLY!" -ForegroundColor Cyan
Write-Host "Runner Up backend and Cloudflare tunnel will now automatically start and run continuously even when your laptop lid is closed." -ForegroundColor Green
